package com.r0ybt.arachn0de.bank

import org.json.*

internal object BankJson {
    private fun text(o:JSONObject,k:String):String {val v=o.get(k);require(v is String && v.length<=10000);return v}
    private fun optional(o:JSONObject,k:String,nullable:Boolean):String? = if(nullable && o.isNull(k)) null else text(o,k)
    private fun number(o:JSONObject,k:String):Long {val v=o.get(k);require(v is Int || v is Long);return (v as Number).toLong()}
    private fun flag(o:JSONObject,k:String):Boolean {val v=o.get(k);require(v is Boolean);return v}
    fun roots(rows:List<BankRoot>)=JSONArray(rows.map {r->JSONObject().apply {put("id",r.id);}})
    fun readRoots(a:JSONArray):List<BankRoot> {require(a.length()<=100000);return (0 until a.length()).map {i->val o=a.getJSONObject(i);require(o.keys().asSequence().toSet()==setOf("id"));BankRoot(text(o,"id"))}}
    fun accounts(rows:List<BankAccount>)=JSONArray(rows.map {r->JSONObject().apply {put("id",r.id);put("rootId",r.rootId);put("personId",r.personId ?: JSONObject.NULL);}})
    fun readAccounts(a:JSONArray):List<BankAccount> {require(a.length()<=100000);return (0 until a.length()).map {i->val o=a.getJSONObject(i);require(o.keys().asSequence().toSet()==setOf("id","rootId","personId"));BankAccount(text(o,"id"),text(o,"rootId"),text(o,"personId"))}}
    fun operations(rows:List<BankOperation>)=JSONArray(rows.map {r->JSONObject().apply {put("id",r.id);put("rootId",r.rootId);put("contextAccountId",r.contextAccountId ?: JSONObject.NULL);put("kind",r.kind);put("amount",r.amount);put("day",r.day);put("concept",r.concept);put("sourceAccountId",r.sourceAccountId ?: JSONObject.NULL);put("destinationAccountId",r.destinationAccountId ?: JSONObject.NULL);put("sourcePersonId",r.sourcePersonId ?: JSONObject.NULL);put("obligationPersonId",r.obligationPersonId ?: JSONObject.NULL);put("correctsId",r.correctsId ?: JSONObject.NULL);put("voided",r.voided);put("createdAt",r.createdAt);}})
    fun readOperations(a:JSONArray,nullable:Boolean=false):List<BankOperation> {require(a.length()<=100000);return (0 until a.length()).map {i->val o=a.getJSONObject(i);require(o.keys().asSequence().toSet()==setOf("id","rootId","contextAccountId","kind","amount","day","concept","sourceAccountId","destinationAccountId","sourcePersonId","obligationPersonId","correctsId","voided","createdAt"));BankOperation(text(o,"id"),text(o,"rootId"),optional(o,"contextAccountId",nullable),text(o,"kind"),number(o,"amount"),number(o,"day"),text(o,"concept"),if(o.isNull("sourceAccountId")) null else text(o,"sourceAccountId"),if(o.isNull("destinationAccountId")) null else text(o,"destinationAccountId"),if(o.isNull("sourcePersonId")) null else text(o,"sourcePersonId"),if(o.isNull("obligationPersonId")) null else text(o,"obligationPersonId"),if(o.isNull("correctsId")) null else text(o,"correctsId"),flag(o,"voided"),number(o,"createdAt"))}}
    fun allocations(rows:List<BankAllocation>)=JSONArray(rows.map {r->JSONObject().apply {put("id",r.id);put("operationId",r.operationId);put("nodeId",r.nodeId);put("amount",r.amount);put("personId",r.personId ?: JSONObject.NULL);put("personName",r.personName ?: JSONObject.NULL);put("sourcePersonId",r.sourcePersonId ?: JSONObject.NULL);put("sourcePersonName",r.sourcePersonName ?: JSONObject.NULL);put("title",r.title);put("ruleId",r.ruleId ?: JSONObject.NULL);put("occurrenceDay",r.occurrenceDay ?: JSONObject.NULL);put("stateAt",r.stateAt ?: JSONObject.NULL);put("stateCount",r.stateCount);}})
    fun readAllocations(a:JSONArray,nullable:Boolean=false):List<BankAllocation> {require(a.length()<=100000);return (0 until a.length()).map {i->val o=a.getJSONObject(i);require(o.keys().asSequence().toSet()==setOf("id","operationId","nodeId","amount","personId","personName","sourcePersonId","sourcePersonName","title","ruleId","occurrenceDay","stateAt","stateCount"));BankAllocation(text(o,"id"),text(o,"operationId"),text(o,"nodeId"),number(o,"amount"),optional(o,"personId",nullable),optional(o,"personName",nullable),optional(o,"sourcePersonId",nullable),optional(o,"sourcePersonName",nullable),text(o,"title"),if(o.isNull("ruleId")) null else text(o,"ruleId"),if(o.isNull("occurrenceDay")) null else number(o,"occurrenceDay"),if(o.isNull("stateAt")) null else number(o,"stateAt"),number(o,"stateCount") .also {require(it in 2L..3L)}.toInt())}}
}
